def signal(obs):
    s = obs.state
    if 'pos' not in s:
        s['pos'] = 0  # spread position: +1 long spread (long IDX short basket), -1 short spread
    wA = 0.3333
    wB = 0.6667
    wC = 0.1667
    thr_enter = 14.0
    thr_exit = 4.0
    try:
        # need enough history for stable mids
        n = 20
        A = obs.hist('A','mid', n)
        B = obs.hist('B','mid', n)
        C = obs.hist('C','mid', n)
        IDX = obs.hist('IDX','mid', n)
        if A is None or B is None or C is None or IDX is None:
            return {}
        if len(A) < 5 or len(IDX) < 5:
            return {}
        # get last valid mids
        def last_valid(arr):
            for i in range(len(arr)-1, -1, -1):
                v = arr[i]
                if np.isfinite(v):
                    return float(v)
            return float('nan')
        a = last_valid(A)
        b = last_valid(B)
        c = last_valid(C)
        idx = last_valid(IDX)
        if not (np.isfinite(a) and np.isfinite(b) and np.isfinite(c) and np.isfinite(idx)):
            return {}
        basket = wA*a + wB*b + wC*c
        spread = idx - basket
        if not np.isfinite(spread):
            return {}
        pos = int(s['pos'])
        # hysteresis: enter when |spread| > thr_enter, exit when |spread| < thr_exit
        if pos == 0:
            if spread > thr_enter:
                pos = -1
            elif spread < -thr_enter:
                pos = 1
            else:
                pos = 0
        elif pos == -1:
            # short spread, waiting to cover
            if spread < thr_exit:
                pos = 0
            elif spread < -thr_enter:
                # flip to opposite if spread crosses far to other side
                pos = 1
            else:
                # hold short
                pass
        elif pos == 1:
            if spread > -thr_exit:
                pos = 0
            elif spread > thr_enter:
                pos = -1
            else:
                pass
        s['pos'] = pos
        # map spread position to asset targets
        # pos = 1 => long IDX, short basket; pos=-1 => short IDX, long basket
        # use exact hedge ratios, no amplification to stay dollar neutral
        p_idx = float(pos) * 1.0
        # basket legs opposite sign, sized by weights
        pA = -float(pos) * wA
        pB = -float(pos) * wB
        pC = -float(pos) * wC
        # clip to [-1,1]
        pA = float(np.clip(pA, -1, 1))
        pB = float(np.clip(pB, -1, 1))
        pC = float(np.clip(pC, -1, 1))
        p_idx = float(np.clip(p_idx, -1, 1))
        out = {}
        out['IDX'] = p_idx
        out['A'] = pA
        out['B'] = pB
        out['C'] = pC
        out['A.X'] = 0.0
        out['B.X'] = 0.0
        out['C.X'] = 0.0
        return out
    except:
        return {}

